CREATE TABLE IF NOT EXISTS bindings (id TEXT PRIMARY KEY CHECK(id GLOB 'bnd_*'), asset_id TEXT NOT NULL, owner_user_id TEXT NOT NULL REFERENCES users(id), agent_id TEXT NOT NULL REFERENCES agents(id), harness_id TEXT NOT NULL REFERENCES harnesses(id), version INTEGER NOT NULL, created_at TEXT NOT NULL, revoked_at TEXT, UNIQUE(asset_id,owner_user_id,agent_id,harness_id,version)); CREATE INDEX IF NOT EXISTS bindings_scope ON bindings(owner_user_id,agent_id);